mapper.insert:
INSERT
  INTO TBL_REVIEW
(
  REVIEW_NO
, PROD_NO
, OPT_COMB_NO
, ORDER_ITEM_NO
, MEMBER_ID
, REVW_CONTENT
, REVW_REG_DATE
, REVW_RATINGS
)
VALUES
(
  SEQ_REVIEW_NO.NEXTVAL
, #{ prodNo }
, #{ optCombNo }
, #{ orderItemNo }
, #{ memberId }
, #{ revwContent }
, SYSDATE
, #{ revwRatings }
)

INSERT
  INTO TBL_ATTACHMENT
(
  ATTACHMENT_NO
, REF_PROD_NO
, REF_REVW_NO
, ORIG_FILE_NM
, SAVE_FILE_NM
, SAVE_PATH
, THUMBNAIL_PATH
, FILE_TYPE
, ATTACH_STATUS_YN
)
VALUES
(
  SEQ_ATTACH_NO.NEXTVAL
, NULL
, #{ refRevwNo }
, #{ origFileNm }
, #{ saveFileNm }
, #{ savePath }
, #{ thumbnailPath }
, #{ fileType }
, DEFAULT
)
